/** Machine translated draft; religious and linguistic review pending. */
internal object DuaBrxDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_q_lut_najjini_ahli" to DuaText("दुआ अफ लुत (एएस)-सेव माय फेमिलि।", "आंनि इसोर, आंखौ आरो आंनि नखरखौ बिसोर मा खालामो (फिथाय) निफ्राय रैखा खालाम।", "गावनि नखरखौ गाज्रि थासारिनिफ्राय रैखा खालामनाय।", "नख'रखौ गाज्रिनिफ्राय रैखा खालाम।"),
        "dua_q_sulaiman_awzini" to DuaText("अन्थोबनि थाखाय सुलेमान (ए. एस.) नि दुआ।", "आंनि इसोर, नों आंनो आरो आंनि बिमा-बिफाखौ होनाय नोंनि अनथोबनि थाखाय आंनो बाखनायनो हो, आरो नोंखौ गोजोनहोनाय मोजां खामानि मावनो, आरो नोंनि अननायजों नोंनि गोथार बान्दाफोरनि गेजेराव आंखौ गनायथि होनो हो।", "बोरनि थाखाय बाखनायनाय गोहोनि थाखाय।", "सुलेमान (ए. एस.) नि बाखनायनायनि दुआ।"),
        "dua_q_musa_zalamtu" to DuaText("मुसा (ए. एस.) नि दुआ-आं गावखौ गोरोन्थि खालामदोंमोन।", "आंनि इसोर, आं गावखौ अनागारि खालामदों, बेनिखायनो आंखौ बावगार।", "गोरोन्थि जानायनि उनाव थाबैनो उनदाहा।", "अल्लाहआ मुसाखौ (ए. एस.) बावगारदोंमोन।"),
        "dua_q_musa_najjini" to DuaText("मुसा (ए. एस.) नि दुआ-आंखौ अनागारिफोरनिफ्राय रैखा खालाम।", "आंनि इसोर, आंखौ गोरोनथि खालामग्रा सुबुंफोरनिफ्राय बासायनांगौ।", "जेब्ला अनागारिफोरखौ गियो।", "मुसानि दुआ (एएस) जेब्ला मिस्रखौ नागारदों।"),
        "dua_q_lut_unsurni" to DuaText("लुटनि दुआ (एएस)-गाज्रि खालामग्राफोरनि बेरेखायै मदद।", "आंनि इसोर, गाज्रि खालामग्रा सुबुंफोरनि बेरेखायै आंखौ मदद खालाम।", "जायफ्रा गाज्रि आखुथाइ गोसारहोयो, बिसोरनि बेरेखायै मददनि थाखाय।", "जाय सैथोआव दिदोम गसंना थायो, बिसोरनि दुआ।"),
        "dua_q_hab_li_salihin" to DuaText("इब्राहिमनि दुआ (एएस) सासे गोथार गथ'नि थाखाय।", "आंनि इसोर, आंनो गोथार सुबुंफोरनि गेजेरावनिफ्राय (सासे गथ') खौ हो।", "गोथार गथ'फोरनि थाखाय सोंनाय।", "बेनि गेजेरजों दुआ इसमाइल (एएस) खौ गनायथि होनाय जादोंमोन।"),
        "dua_q_wasita_kulla_shay" to DuaText("राजउलाफादखौ बोजानाय फेरेशतफोरनि दुआ", "जोंनि इसोर, नों गासैबो जिनिसफोरखौ अननाय आरो गियानजों खोबथेयो, बेनिखायनो जायफोरा उनदाहा लायो आरो नोंनि लामाखौ सोलियो, बिसोरखौ क्षमा खालाम आरो बिसोरखौ जाहान्नामनि साजानिफ्राय रैखा खालाम।", "राजउलाफादखौ बोजानाय फेरेशताफोरा फोथायग्राफोरनि थाखाय बे दुआखौ बानायो।", "फेरेशतफोरनि दुआआव सोफादेरनायनि थांखिजों फरायदोंमोन।"),
        "dua_q_ikhwanina" to DuaText("जोंनि बिदा-फंबायफोरनि थाखाय जाय जोंनि सिगांमोन।", "ऐ जोंनि इसोर, नोंखौ आरो जोंनि बिदा-फंबायफोरखौ, जाय जोंनि सिगां फोथायनायाव दंमोन, आरो जायफोरा फोथायो, बिसोरनि फारसे जोंनि गोसोयाव रागाखालामनो नाङा। जोंनि इसोर, नों थारैनो अनजाथाव आरो अनजाथाव।", "मोनसे दुआ बै फोथायगिरिफोरनि थाखाय जाय सिगां फैदोंमोन आरो मोनसे गोथार बिखानि थाखाय।", "गोजौ थाखोनि लोगोफोर (आर. ए.) आरो सिगांनि फोथायगिरिफोरनि थाखाय मोनसे दुआ।"),
        "dua_q_alayka_tawakkalna" to DuaText("नोंनि सायाव जों सोनारना दं (इब्राहिम ए. एस.)।", "ऐ जोंनि इसोर, जों नोंनि सायाव सोनारो, जों नोंनि फारसे गिदिंबो आरो नोंनि फारसे फैफिनो। जोंनि इसोर, नोङो जोंनि सायाव फोथायनो हायैफोरनि थाखाय आनजाद खालाम आरो नोंखौ क्षमा खालाम। जोंनि इसोर, नों थारैनो गोहोगोरा, गियानगोनां।", "इब्राहिम (ए. एस.) आरो बिथांनि लोगोफोरनि दुआ।", "अल्लाहनि सायाव सोनारनाय आरो बिथांनि फारसे गिदिंनायनि मोनसे दुआ।"),
        "dua_q_atmim_nurana" to DuaText("जोंनि सोरांखौ आबुं खालाम।", "जोंनि इसोर, जोंनि थाखाय जोंनि सोरांखौ आबुं खालाम आरो नोंखौ क्षमा खालाम। थारैनो, नोंहा गासैबो जिनिसफोरनि सायाव गोहो दं।", "पुनरुत्थाननि सानाव फोथायगिरिफोरनि दुआ।", "सिरातआव सोरांनि थाखाय सोंनाय।"),
        "dua_q_asiya_baytan" to DuaText("आसियानि दुआ-जान्हायाव मोनसे न'।", "आंनि इसोर, आंनि थाखाय सोरगोआव मोनसे न'लु, फैरो आरो बिनि खामानिफोरनिफ्राय आंखौ रैखा खालाम आरो गोरोन्थि खालामग्रा सुबुंफोरनिफ्राय आंखौ रैखा खालाम।", "आसियानि दुआ, फार'ननि बिसि।", "अल्लाहआ बिथांखौ फोथायग्राफोरनि थाखाय मोनसे बिदिन्थि बानायदोंमोन।"),
        "dua_adhan_response" to DuaText("अधानखौ फिन हो।", "अल्लाहनि अनगा जेबो गोहो आरो गोहो गैया।", "मुअज्जिनआ जायखौ बुङो बेखौ खालामफिन;'हय'आलास-सालाह'आरो'हय'अलाल-फालाह'आव बे बाथ्रा बुं।", "जाय गोसोनिफ्राय फिन होयो बियो सोरगोआव हाबगोन।"),
        "dua_adhan_shahadah" to DuaText("मुअज्जिननि शहादानि उनाव", "आरो आंबो साखि होयो दि अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, हारसिङै, बाहागोआरि गैयालासे, आरो मुहम्मद सलिहआ बिथांनि बान्दा आरो रसूला। आं अल्लाहजों इसोर महरै, मुहम्मद सलिहआ रसूला महरै आरो इस्लामखौ धोरोम महरै गोजोनदों।", "मुएज़िनि फोथायनायनि साखि खोनानाय।", "बिनि पापफोरा क्षमा खालाम जायो।"),
        "dua_istiftah_baid" to DuaText("दुआखौ खुलिनाः आंखौ पापफोरनिफ्राय गोजानाव दोन।", "ऐ अल्लाह, आंनो आंनि पापफोरनिफ्राय गोजानाव दोन मानोना नों सानजानिफ्राय सोनाबसिम गोजानाव दोनबाय। ऐ अल्लाह, आंनो पापफोरनिफ्राय साफा खालाम जेरै गुफुर जिखौ मैलानिफ्राय साफा खालामनाय जायो। ऐ अल्लाह, आंनि पापफोरखौ दै, बरफ आरो अखाफोरजों सु।", "बेखेवनायनि उनाव (सानानि जायगायावबो बुंनाय जायो)।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ तकबीर आरो फरायनायनि गेजेराव फरायदोंमोन।"),
        "dua_hamdan_kathiran" to DuaText("रुकुनि उनाव गोबां बाखनायनाय।", "जोंनि इसोर, नोंनो बाख्नायनायनाय दं-गोबां, गोथार आरो बोरगोनां बाख्नायनायनाय।", "रुकुनिफ्राय ओंखारनायनि उनाव,'रब्बाना लकल-हमद'जों लोगोसे।", "थामजिनिबो बांसिन फेरेशताफोरा बेखौ गिबिसिन रेबगान्थि खालामनो थाखाय खारगासिनो दंमोन।"),
        "dua_subbuhun_quddus" to DuaText("सुब्बूहुन कुद्दुस (रुकु आरो सुजूद)", "(अल्लाहआ) बयनिख्रुइबो गोग्गानाय, बयनिख्रुइबो गोथार, फेरेशताफोर आरो जिउमानि (जिब्रिल) इसोर।", "रुकू आरो सुजूदआव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ रुकू आरो सुजूदआव फरायदोंमोन।"),
        "dua_sujood_dhanbi_kullah" to DuaText("सुजूदः आंनि गासिबो पापफोरखौ बावगार।", "ऐ अल्लाह, आंनि गासिबो पापफोरखौ-फिसा आरो गेदेर, गिबि आरो जोबथा, गेवनाय आरो खोबजानायखौ आंनो क्षमा खालाम।", "सुजूदआव।", "प्रस्ट्रेशनआ मोनसे जायगा जेराव दुआफोरनि फिन होनाय जायो।"),
        "dua_sujood_ridaka" to DuaText("नोंनि गोजोननायाव आश्रय ला।", "ऐ अल्लाह, आं नोंनि रागा जों नोंनि गोजोननायाव, नोंनि साजा निफ्राय नोंनि क्षमा आव, आरो आं नोंनिफ्राय नोंनि सिङाव आश्रय नागिरो। आं नोंखौ आबुं बाख्नायनो हाया; नों गावनिनो बाख्नायनायनाय बायदि।", "सुजूदआव आयशा (रा.) आ पैगम्बर सल्लल्लाहु अलैहि वसल्लमखौ बे बाथ्रा बुंनायखौ खोनानायसै।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमनि मोनसे सुजूद दुआ।"),
        "dua_tashahhud" to DuaText("ताशाहहुद (अत-ताहियात)", "गासैबो रावारि, देहायारि आरो रांखान्थियारि सिबिथायनि हाबाफोरा अल्लाहनि थाखाय। हे पैगम्बर, नोंनि सायाव गोजोन आरो अल्लाहनि अननाय आरो बिथांनि बोरफोर। जोंनि सायाव आरो अल्लाहनि गोथार बान्दाफोर सायाव गोजोन। आं साखि होयो दि अल्लाहनि अनगा रावबो सिबिजानायनि मोन्थाइ गैया, आरो आं साखि होयो दि मुहम्मद स'ल'हआ बिथांनि बान्दा आरो पैगंबर।", "मोनफ्रोमबो जिरायनायाव-अब्दुल्ला इब्न मसूद (र.) (हनाफी सर') जों बरनायजानाय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बेखौ कुराननि सूराह बायदि फोरोंदोंमोन।"),
        "dua_sajdah_tilawah" to DuaText("फरायनायनि साजदा", "आंनि मोखांआ बैनो साथि होदोंमोन जाय बेखौ सोरजिदोंमोन आरो गावनि गोहो आरो गोहोजों बिनि खोनानाय आरो नुथायखौ दिहुनदोंमोन।", "साबद्रायनायाव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा हराव साबद'द गाबनानै बे बाथ्रा बुंदोंमोन।"),
        "dua_after_witr" to DuaText("विटरनि उनाव", "बयनिख्रुइबो गोथारसिन, राजानो गोग्गां।", "विदरनि सालामनि उनाव खेबथाम, थामथि खेब गारांखौ गोजौ खालाम।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बेखौ विदरनि उनाव बुंदोंमोन।"),
        "dua_tahajjud_nur" to DuaText("ताहाज्जुदखौ बेखेवनायनि आरज।", "ऐ अल्लाह, नोंनो बाख्नायनायनाय दं; नोंनो सोरगो, बुहुम आरो बिसोरनि सिङाव गासिबोनि खांग्रा। नोंनो बाख्नायनायनाय। नोंनो बाख्नायनाय, बुहुम आरो बिसोरनि सिङाव गासिबो सोरां। नोंनो बाख्नायनायनाय। नोंनो साखि, नोंनि बावनाया सैथो, नोंजों लोगो मोननाया सैथो, नोंनि बाथ्रा सैथो, सोरगोआ सैथो, जाहान्नामा सैथो, पैगंबरफोरा सैथो, मुहम्मद स'लिहा अलैहि वस्लमा सैथो आरो घड़ीआ सैथो।", "जेब्ला हर आरजखौ (तहज्जुद) (दुआनि जागायजेन्नाय बाहागो) जागायो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा ताहज्जुदनि थाखाय ओंखारनायाव बेखौ फरायदोंमोन (आबुं दुआआ अल-बुखारीआव दं)।"),
        "dua_rabba_jibrail" to DuaText("नांलाय-मोन्नायनि आयदाफोराव आंनो लामा दिन्थि।", "ऐ जिब्रिल, मीकाईल आरो इसराफिलनि इसोर, सोरगो आरो बुहुमनि सोरगिरि, नुजायै आरो नुजानायखौ मिन्थिग्रा! नों नोंनि बान्दाफोरनि गेजेराव बे बाथ्राखौ बिजिरगोन जाय बिसोर गेजेराव फाराग दंमोन। नों गनायथि होनानै आंखौ बै सैथोनि फारसे लामा दिन्थि जायखौ लानानै फारागथि दं। थारैनो, नोंथाङा जायखौ मोनसे थोंगोर लामायाव दैदेनगोन।", "ताहज्जुदनि जागायनायाव-गोरोबलायैनि गेजेराव सैथोनि थाखाय लामा दिन्थिग्रा।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गावनि हर आरजखौ बे दुआजों जागायदोंमोन।"),
        "dua_going_to_mosque_nur" to DuaText("मस्जिदाव थांनाय (सोरांनि दुआ)", "ऐ अल्लाह, आंनि बिखुङाव सोरां हो, आंनि मेगनाव सोरां, आंनि खोमाफोराव सोरां, आंनि आगदाथिं सोरां, आंनि आगसिथिं सोरां, आंनि सायाव सोरां, आंनि गाहायाव सोरां, आंनि सिगाङाव सोरां, आंनि उनथिं सोरां आरो आंनि थाखाय सोरां खालाम।", "फजरनि थाखाय मस्जिदाव थांनाय समाव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा आरज गाबनो ओंखारबोयोब्ला बेखौ फरायदोंमोन।"),
        "dua_waswasa_salah" to DuaText("सालाहनि समाव वासवासा (खिन्जाब)", "आं शापित शयताननिफ्राय अल्लाहनि शरण लायो।", "जेब्ला आरज गाबनाय समाव शेताननि फिसुख्रै बाथ्रा फैयो, अब्ला आश्रय ला आरो थाम खेब आगसिथिं एसे गोरान थुख्र'।", "उथमान इब्न अबिल -'आस (रा.) आ बे बायदि खालामदोंमोन आरो फिसुरनायफ्रा खारलांदोंमोन।"),
        "dua_alimal_ghayb" to DuaText("नुजायैखौ मिन्थिग्रा।", "ऐ अल्लाह, नायजायै आरो नुजानायखौ मिन्थिग्रा, सोरगो आरो बुहुमनि सोरगिरि, सोरगो आरो गासैबो जिनिसफोरनि सोरगोआरि! आं साखि होयो दि नोंनि अनगा रावबो इसोर गैया। आं आंनि गावनि गाज्रिनिफ्राय, शयताननि गाज्रिनिफ्राय आरो बिनि (लिंहरग्रा) सिरकनिफ्राय नोंनि सिङाव शरण नागिरो।", "फुं, बेलासिं आरो उनदुनो सिगां-पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ आबु बकर (र.) नो फोरोंदोंमोन।", "गावनि आरो शयताननि गाज्रिनिफ्राय रैखा खालाम।"),
        "dua_fitratil_islam" to DuaText("इस्लामनि फित्रायाव", "जों इस्लामनि फित्रायाव, गोथारथिनि सोदोबजों, जोंनि पैगंबर मुहम्मद सल्लल्लाहु अलैहि वस्लमनि धोरोम आरो जोंनि बिफा इब्राहिम (ए. एस.) नि लामायाव फुंआव हाबदोंमोन, जाय थि आरो मुसलमानमोन आरो गोबां इसोरनि नङामोन।", "फुंआव।", "सानफ्रोमबो फुंआव गावनि फोथायथिखौ गोदान खालामफिन।"),
        "dua_amsayna_fitrah" to DuaText("इस्लामनि फित्रायाव बेलासिं।", "जों इस्लामनि फित्रायाव, गोथारथिनि सोदोबजों, जोंनि पैगंबर मुहम्मद सल्लल्लाहु अलैहि वस्लमनि धोरोम आरो जोंनि बिफा इब्राहिम (ए. एस.) नि लामायाव, जाय थि आरो मुसलमानमोन आरो गोबां इसोरनि नङामोन, बेलासियाव हाबदोंमोन।", "बेलासियाव।", "सानफ्रोमबो बेलासियाव गावनि फोथायथिखौ गोदान खालामफिन।"),
        "dua_tahleel_10_fajr" to DuaText("फजर आरो माघरिबनि उनाव जि तहलील।", "अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे। बिथांनिनो रायजो आरो बिथांनिनो बाख्नायनायनाय; बिथाङा जिउ होयो आरो थैहोयो, आरो बिथाङा गासैबो जिनिसनि सायाव गोहो दं।", "फजर (आरो माघरिब) नि जि खेब उनाव, गावनि जिरायना थानाय एबा रायज्लायनायनिफ्राय ओंखारनायनि सिगां।", "जि मोजां खामानिफोर, जि पापफोरा फोजोबस्रां जायो, जि थाखोफोरखौ फेहेरनाय जायो आरो सानसेनाङै शयताननिफ्राय रैखा खालामनाय जायो।"),
        "dua_la_hawla_kanz" to DuaText("जान्नानि मोनसे धोन", "अल्लाहनि अनगा जेबो गोहो आरो गोहो गैया।", "गोबां समावनो, गासैबो समावनो।", "बेयो सोरगोनि धोनफोरनि गेजेराव मोनसे।"),
        "dua_four_beloved_words" to DuaText("मोनब्रै जोबोर मोजां मोनजानाय सोदोबफोर", "अल्लाहनो महिमा, गासिबो बाख्नायनाया अल्लाहनि थाखाय, अल्लाहनि अनगा रावबो बाख्नायजानायनि मोन्थाइ गैया, आरो अल्लाहानो देरसिन।", "बे सोदोबफोरा अल्लाहनो जोबोर मोजां मोनजानाय।", "बिसोर पैगंबरनि थाखाय सान ओंखारनायनि गासैबोनिबोख्रुइ बांसिन मोजां मोन।"),
        "dua_two_light_words" to DuaText("रावाव मोननै सोदोबफोर।", "गौथावनाया अल्लाहनो आरो गासिबो बाखनायनाया बिनि; गोग्गानायआ अल्लाहनो, जाय गेदेर।", "खुगाआव रेजें, स्केलाव गिलिर।", "बयनिख्रुइबो बांसिन अनजाथावखौ मोजां मोनो, खुगाआव रेजें आरो स्केलआव गिलिर। (बुखारीनि जोबथा हादीस)"),
        "dua_ya_dhal_jalal" to DuaText("या धल-जलाली वाल-इकराम", "ओ महामान्या आरो माननि बिगोमा!", "बेखौ दुआआव लाखि-पैगंबरनि सलायह अलैहि वस्लम बिथोन।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बुङोः'या धल-जलाली वाल-इकराम'खौ हमथा।"),
        "dua_sleep_wadatu_janbi" to DuaText("नोंनि मुंजों आं जिरायो।", "आंनि इसोर, आं नोंनि मुंजों आंनि फारसेखौ दोनदों आरो नोंनि मुंजों आं ओंखारदों। जुदि नों आंनि जिउमाखौ लायो, अब्ला बिनि सायाव अननाय हो, आरो जुदि नोंथाङा बेखौ हगारो, अब्ला बेखौ रैखा खालाम जेरै नोंथाङा नोंथांनि गोथार सिबिग्राफोरखौ रैखा खालामो।", "हासुदैखौ हाद्रि आरो उन उन।", "उन्दुनायनि सिगां गावनि जिउमाखौ अल्लाहनो बावनाय।"),
        "dua_sleep_khalaqta_nafsi" to DuaText("नों आंनि जिउमाखौ सोरजिदों।", "ऐ अल्लाह, नों आंनि जिउमाखौ सोरजिदों आरो नों बेखौ लानो हागोन। बिनि थैनाय आरो बिनि जिउआ नोंनि। जुदि नों बेखौ थांना दोनदोंब्ला बेखौ रैखा खालाम आरो जुदि नों बिखौ थैनो होदोंब्ला बेखौ बावगार। ऐ अल्लाह, आं नोंखौ मोजांनि थाखाय आरज गाबदों।", "उनदुनाय सिगां-इब्न उमर (रा.) जों सल'जानाय।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ उनदुङाव बुंनो बिथोन होदोंमोन।"),
        "dua_sleep_atamana" to DuaText("उन्दुनायनि सिगां अनथोब हो।", "गासिबो बाख्नायनाया अल्लाहनि थाखाय जाय जोंनो जाहैयो, दै लोंहोयो, थोजासे दै होयो आरो जोंनि थाखाय आश्रय होयो। ओरैबायदि बेसेबां दं जायहा थोजासे नङा एबा बिसोरनो आश्रय होनो रावबो गैया।", "जेब्ला उनदुनो थाङो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा एमाव थांब्ला बे बाथ्राखौ बुंदोंमोन।"),
        "dua_sleep_rabbas_samawat" to DuaText("सोरगोनि इसोर-जोंनि दाहारखौ हो।", "ऐ अल्लाह, सोरगो, बुहुमनि आरो गोहोगोरा राजउलाफादनि इसोर, जोंनि इसोर आरो गासैबो जिनिसनि इसोर, बेगर आरो ख'र'अन्थाइनि रानगिरि, तोराह, इंजिल आरो फुरकाननि फोसावगिरि! आं नोंनाव गासिबो गाज्रिनिफ्राय रैखा नागिरो जायनि सिगांथिं नों हमथाबो। ऐ अल्लाह, नोंनो गिबि, नोंनि सिगाङाव जेबो गैया; नोंनो जोबथा, नोंनि उनाव जेबो गैया; नोंनो जेबो रोखा नङा, नोंनि गोजौथिं जेबो गैया; नोंनो खोबथेनाय, नोंनिफ्राय जेबो खोबथेनाय गैया। जोंनि दाहारखौ थि खालाम आरो नोंखौ निखावरिनिफ्राय उदां खालाम।", "उनदुनो सिगां, आगदा फारसे जिरायना-फातिमाह (रा.) नो फोरोंनाय।", "दाहार आरो गोब्राबनिफ्राय रैखा मोननो थाखाय मोनसे दुआ।"),
        "dua_sleep_fear" to DuaText("उनदुनो थाखाय गिनांगौ एबा गोजोन गैयै।", "आं अल्लाहनि आबुं सोदोबफोराव बिथांनि रागा आरो बिथांनि साजा, बिथांनि बान्दाफोरनि गाज्रिनिफ्राय, आरो शय़तानफोरनि फिसुख्रैनिफ्राय आरो बिसोर आंनि खाथियाव फैनायनिफ्राय रैखा नागिरो।", "जेब्ला उनदुनो समाव गियो एबा गोजोन गैयै मोनो।", "बेबादि खालामब्ला, बै बाथ्राया बिखौ खहा खालामाखैमोन।"),
        "dua_waking_afani" to DuaText("जागोदानः बियो आंनि जिउखौ फिन जोनोम होदोंमोन।", "गासिबो बाख्नायनाया अल्लाहनि थाखाय जाय आंनि देहाखौ मोजां होदोंमोन, आंनि जिउमाखौ आंनो होफिन्दोंमोन आरो आंखौ बिथांखौ गोसोखांनो गनायथि होदोंमोन।", "जागोदानाव।", "मोनसे गोदान फुंनि थाखाय बाखनाय।"),
        "dua_allahu_rabbi" to DuaText("अल्लाह, अल्लाहआ आंनि इसोर।", "अल्लाह, अल्लाहआ आंनि इसोर; आं बेजों जेबो सोमोन्दो गैया।", "दुखु एबा दुखुआव-पैगम्बर सल्लल्लाहु अलैहि वस्लमा आसमा बिनत उमायस (रा.) नो बेखौ फोरोंदोंमोन।", "दुखु मोननायाव तौहिदखौ हमथाना दोन।"),
    )
}
